class Solution:
    def orangesRotting(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        DIR = [0, 1, 0, -1, 0]
        fresh = 0
        queue = deque()

        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    fresh += 1
                if grid[i][j] == 2:
                    queue.append((i, j))

        time = 0
        while queue and fresh > 0:
            k = len(queue)
            for _ in range(k):
                r, c = queue.popleft()
                for i in range(4):
                    nr, nc = r + DIR[i], c + DIR[i + 1]
                    if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 1:
                        queue.append((nr, nc))
                        grid[nr][nc] = 2
                        fresh -= 1

            time += 1

        return time if fresh <= 0 else -1
